    key, k_ = random.split(key)
    scale = jnp.sqrt(6.0 / 9)
    params.append((random.uniform(k_, (1152, 1, 3, 3), minval=-scale, maxval=scale),
                   jnp.ones(1152), jnp.zeros(1152)))
    # SE down 1152→48
    key, k_ = random.split(key)
    scale = jnp.sqrt(6.0 / 48)
    params.append((random.uniform(k_, (48, 1152, 1, 1), minval=-scale, maxval=scale), jnp.zeros(48)))
